INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1323315-ise496', 'stk-user2352', 'ISE 496', 'info', '{"desc": "السلام عليكم\n\nيسرني في هذا الموضوع كتابة نماذج للتفكير الإستراتيجي لصناعة القرار وهو ما استفدته من المادة ISE-496 .\nhttp://store1.up-00.com/2014-01/1390856272941.jpgمركز تحميل الصور\nمثلث إتخاذ القرار ،،\n\nهذا المثلث يوضح العوامل التي تؤثر على إتخاذ القرار،،\n\nفإذا أتجه السهم من أسفل (الشهوة) إلى الأعلى (الفكر) كان القرار خاطئ وأقرب إلى الفشل،،\n\nأما إذا كان إتجاهه من الأعلى (الفكر) إلى الأسفل (الشهوة ) كان أقرب للصواب…\n\nعندما تواجهنا الفوضى، نسعى للوصول إلى وسائل تنظيمها، أو لإدراك حقيقتها، أو على الأقل الوصول إلى رؤية واضحة عامة لها.\n\nhttp://store1.up-00.com/2014-01/1390856928981.jpgمركز تحميل الصور\nتحليل رباعي\n\nبيان للتحليل الرباعي أو ما يعرف ب SWOT\nيستخدم التحليل الرباعي )باإلنجليزية: SWOT( كأداة تحليل استراتيجي عامة في عدة\nمجاالت كإدارة األعمال والتسويق والتنمية البشرية وغيرىا. وينقسم ىذا التحليل كما كتبت\nحروفو األربعة باإلنجليزية إلى S-W-O-T ويمكن تعريفها كما يلي:\n القوة : عناصر القوة في المشروع والتي تميزه عن غيره من المشاريع وىى ترجمة\nلكلمة Strengths.\n الضعف : نقاط الضعف في المشروع وىى ترجمة لكلمة Weaknesses.\n الفرص : و ىي التي يمكن أن تأتي من خارج المشروع وقد تؤدي على سبيل المثال\nً يمكن أن تؤدي لزيادة األرباح, وىي ترجمة لكلمة\nإلى زيادة المبيعات وأيضا\n.Opportunities\n التهديدات : وىي التي يمكن أن تأتي من خار ج المشروع وتسبب اضظرابات\nللمشروع وىي ترجمة لكلمة Threats. االستفادة من التحليل الرباعي\nً ومثاالً على ذلك\nببساطة شديدة, يتم النظر إلى القوة والفرص ثم تتم عملية دمجهما معا :\nً في منتجها \" قوة\". ولذلك البد من أن تزيد مبيعاتها في\nشركة A تمتاز بجودة عالية جدا\nً لها في منطقة جبل علي\nالشرق األوسط “الفرصة”. ولذلك أنشأت فرعا في إمارة دبي لتزيد\nمبيعاتها. تسمى ىذه العملية “الدمج”. أما بالنسبة للضعف وىو جزء من عملية\n“SWOT” فالبد من تحويلو إلى قوة ومثال ذلك : شركة B على الرغم من جودة\nً مقارنة بمنافسيها “ضعف”, فقامت الشركة\nمنتجاتها العالية إال أن أسعارىا مرتفعة جدا\nتمويل الكامل ألي شخص يريد الشراء منها بدالً بإيجاد برنامج ال من البنوك “قوة” وبذلك\nًن الشركات تحول نقاط\nعملت على زيادة مبيعاتها. تسمى ىذه العملية “تحويل” أي أ\nالضعف إلى قوة.\nنموذج SWOT احدى نماذج التخطيط الواسعة التطبيق ويستخدم بصورة كبيرة في\nالتخطيط التشغيلى لكنو غير جيد في التخطيط االستراتيجى\n\nً لعدد أفراد\nً َ ما تكون الخطة التشغيلية لمدة سنة أما الخطة االستراتيجية فتختلف تبعا\nغالبا\nأو إمكانيات المنظمة\n- خطوات النموذج : - الخطوة األولى ] تحليل SWOT : تهتم ىذه الخطوة بتحليل\nعناصر المنظمة بصورة فعالة فالخطوة األولى فيها ىي تحليل نقاط القوة strengths :\nً مثال القيادة المبدغة ورأس\nوىى المميزات التي تتميز بها المنظمة فعالً وىى موجودة حاليا\nالمال المتوافر والخطوة الثانية فيها ىي تحليل نقاط الضعف weaknesses : وىى\nً المساوئ الموجودة ف في المنظمة في الوقت الحالى مثال عدم وجود خطة استراتيجية\nعليا\nأو ضعف الموقف القانونى للمنظمة والخطوة الثالثة ىي تحليل الفرص المحتملة ً في المنظمة لكن يمكن\nopportunities : وىى االيجابيات الغير موجودة حاليا\nالحصول عليها واستغاللها خالل فترة الخطة المقترحة والخطوة الراربعة ىي تحليل\nالمخاطر المحتملة threats : وىى األشياء السلبية الغير موجودة ولكنها تهدد المنظمة\nخالل فترة الخطة\n خطأ شائع : يعتقد أن نقاط القوة ونقاط الضعف ىي عوامل داخلية وأن الفرص\nوالمخاطر ىي عوامل خارجية عن بيئة المنظمة ولكن الصواب ما تم توضيحو\nباألعلى وىو أصل النظرية\n ملحوظة : ال يفضل الزيادة عن عشر نقاط قوة وعشر نقاط ضعف وثالثة احتماالت\nوثالثة مخاطر وال يفضل النقص عن ثالث نقاط قوة وثالث نثاط ضعف وفرصة\nواحدة وخطر واحد\n\n- الخطوة الثانية ] تحديد األىداف : من الخطوة السابقة تستطيع بكل بساطة صياغة\nاألىداف من خالل خطوات بسيطة وىى المحافظة على كل نقطة قوة وتنميتها ىدف\nوعالج كل نقطة ضعف ىدف واستغالل كل فرصة ىدف وتجنب كل خطر ىدف\n مواصفات الهدف الجيد :\nتكتب األىداف بطريقة smart specific محدد وذلك بأن تحدد\nً ومستهدفين فبدالً المستهدف بدقة كم من أن يكون ىدفنا تحسين قدرات\nية وعددا\nالموظفين بل أن يكون تنمية مهاراتهم في االتصال مثالً measurable قابل\nللقياس وعلى المثال السابق نقول تدريب 011 عامل على 4 دورات في فن االتصال\nagreed متفق عليو بين فريق التخطيط وبين المنفذين فلو كان الهدف مستحيالً\nً عن المنفذين ألننا بذلك نحكم عليهم بالفشل\nكان من العبث أن نقره كفريق تخطيط رغماً إقراره بل نتفق على ىدف صعب لكنو\nً لكان من العبث أيضا\nولو كان الهدف سهالً جدا\nً فمثالً ال نقول أننا\nً خياليا\nغير مستحيل realistic واقعى حقيقى وليس ىدفا\nسندرب كل عمال المصنع في شهر واحد على ألف دورة تدريبية أو أننا سنضاعف اإلنتاج\nمليون ضعف خالل سنة ومثل ىكذا أىداف… timed محدد بوقت وذلك بتحديد\nالفترة التي سننجز الهدف فيها\n يفضل كتابة كل ىدف في صفحة مستقلة\n ال تنسى الدمج بين أىداف الخطة االستراتيجية وأىداف الخطة التشغيلية\n\n- الخطوة الثالثة ] تحديد الوسائل لكل ىدف : في كل صفحة ىدف نكتب الوسائل\nالتي ستعيننا على تحقيق ذلك الهدف وىنا الحظ : أن الوسائل يجب أن تصاغ بطريقة\nً أن ىناك عدة طرق اليجاد الوسائل وىى : - البحث في الوسائل\nsmart أيضا\nالقديمة الناجحة - البحث في وسائل المنافسين مع التطوير - السفر لرؤية التجارب\nالجديدة في ىذا المجال - االبداع واالتيان بعمل جديد\n\n- الخطوة الرابعة ] جدول أعمال : وذلك يشمل الهدف ووسائلو والمنفذ والتكلفة\nالمطلوبو\n\nً لترتيب زمنى وعمل\n- الخطوة الخامسة ] الجدول الزمنى : وذلك بترتيب األىداف تبعا\nورقة لكل شهر تتضمن األىداف المطلوب انجازىا خالل ذلك الشهر\n ىذه الورقة تكون نسخة منها مع الفريق ونسخة أخرى مع القيادة\n- الخطوة السادسة ] جدول خاص : وذلك بجمع األىداف المطلوبو من كل شخص أو\nقسم في ورقة واحدة على مدار السنة وتكون منها نسخة مع القائد ونسخة أخرى مع\nالشخص أو معإدارةالقسم\n\nهذا وصف مفيد للكورس ise-496 وأتمنى أن تستفيدوا منه جميعا\nفي صناعة القرار 👍🙂 😆\nكن صانعاً للقرار فربما قرار صغير قد يغير مجرى حياتك ويكون نقطة تحول 👍 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-496/155956/1", "user": "user2352", "ts": 1390857273000, "tid": 155956, "pn": 1}}', 1390857273000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
